{{!-- Styling parameters: class, titleClass, gridClass --}}
{{#with this as |ghostcnStyles|}}
{{#get "tags" filter="visibility:public" limit="100" include="count.posts"}}
{{#if tags}}<section class="ghcn-tag-grid{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}}" aria-label="Topics">
  {{#if ghostcnStyles.heading}}<h2 class="ghcn-tag-grid__title{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">{{ghostcnStyles.heading}}</h2>{{/if}}
  <div class="ghcn-tag-grid__grid{{#if ghostcnStyles.gridClass}} {{ghostcnStyles.gridClass}}{{/if}}">{{#foreach tags visibility="public"}}
    {{#> "components/card" heading=name description=description class=ghostcnStyles.cardClass titleClass=ghostcnStyles.cardTitleClass descriptionClass=ghostcnStyles.descriptionClass variant=ghostcnStyles.cardVariant}}
      {{> "components/button" href=url text="Explore topic" variant="outline" size="sm" class=ghostcnStyles.buttonClass}}
    {{/components/card}}
  {{/foreach}}</div>
</section>{{else}}{{#if ghostcnStyles.emptyText}}<section class="ghcn-tag-grid{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}}"><p class="ghcn-tag-grid__empty">{{ghostcnStyles.emptyText}}</p></section>{{/if}}{{/if}}
{{/get}}
{{/with}}

.ghcn-tag-grid { font-size: 16px; color: var(--foreground); margin-block: 2em; }
.ghcn-tag-grid__title { font-size: 1.5em; line-height: 1.25; margin: 0 0 1em; }
.ghcn-tag-grid__grid { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 1.5em; }
.ghcn-tag-grid__grid > * { min-width: 0; }
.ghcn-tag-grid__empty { color: var(--muted-foreground); }
@media(max-width:900px) { .ghcn-tag-grid__grid { grid-template-columns: repeat(2,minmax(0,1fr)); } }
@media(max-width:620px) { .ghcn-tag-grid__grid { grid-template-columns: 1fr; } }
